from datetime import date, timedelta


class Library:
    def __init__(self, loan_days: int = 14, daily_fine: float = 0.5) -> None:
        self.loan_days = loan_days
        self.daily_fine = daily_fine

        self._books: set[str] = set()
        # book_id -> (user, borrow_date)
        self._loans: dict[str, tuple[str, date]] = {}
        # user -> set of book_ids currently borrowed
        self._user_books: dict[str, set[str]] = {}
        # user -> unpaid fines amount
        self._fines: dict[str, float] = {}

    def add_book(self, book_id: str) -> None:
        self._books.add(book_id)

    def borrow(self, user: str, book_id: str, day: date) -> None:
        if book_id not in self._books:
            raise ValueError(f"Book '{book_id}' is not in the library catalog.")

        if book_id in self._loans:
            raise ValueError(f"Book '{book_id}' is currently borrowed.")

        current_borrowed = self._user_books.get(user, set())
        if self.unpaid_fines(user) > 0 and len(current_borrowed) >= 1:
            raise ValueError(
                f"User '{user}' has unpaid fines and cannot borrow more than one book."
            )

        self._loans[book_id] = (user, day)
        self._user_books.setdefault(user, set()).add(book_id)

    def return_book(self, user: str, book_id: str, day: date) -> float:
        """Return a book; returns the fine charged for this return."""
        loan_info = self._loans.get(book_id)
        if loan_info is None or loan_info[0] != user:
            raise ValueError(f"User '{user}' has not borrowed book '{book_id}'.")

        borrow_date = loan_info[1]
        if day < borrow_date:
            raise ValueError("Return date cannot be earlier than borrow date.")

        # Remove from active loans
        del self._loans[book_id]
        self._user_books[user].remove(book_id)

        # Calculate due date
        due_date = borrow_date + timedelta(days=self.loan_days)

        # Count overdue weekdays (Monday=0 ... Friday=4; Saturday=5, Sunday=6)
        fine = 0.0
        if day > due_date:
            curr = due_date + timedelta(days=1)
            late_weekdays = 0
            while curr <= day:
                if curr.weekday() < 5:
                    late_weekdays += 1
                curr += timedelta(days=1)

            fine = late_weekdays * self.daily_fine
            self._fines[user] = self._fines.get(user, 0.0) + fine

        return fine

    def unpaid_fines(self, user: str) -> float:
        return self._fines.get(user, 0.0)

    def pay(self, user: str) -> None:
        """Pay all fines of the user."""
        self._fines[user] = 0.0
```

